/**
 * Shared vocabulary for the audit capability (T029, ADR-005,
 * data-model.md §5). `AuditEntityType`/`AuditOutcome` are generated by
 * Prisma from `schema.prisma`, but they are business vocabulary fixed by
 * the specification (data-model.md §5, FR-033), not a persistence detail —
 * this codebase has no separate hand-maintained domain enum to duplicate
 * them into, so the domain and application layers import them directly
 * from `@prisma/client`. This is a values/types import from an npm
 * package, not a `src/infrastructure/**` import, so it is unaffected by
 * the ADR-011 boundary lint rules (which only classify internal
 * `src/**` paths).
 */
import type { AuditEntityType, AuditOutcome } from '@prisma/client';

/**
 * What `AuditContextPort` hands back to `AuditRecorder`: the subset of the
 * ambient `RequestContext` (infrastructure/logging/request-context.ts)
 * that is relevant to an audit row, translated into audit-ready shape
 * (e.g. an empty-string IP becomes `undefined`, never a value that would
 * fail the `inet` column). `undefined` fields mean "unknown in this
 * context" (e.g. no session yet, no client IP recorded), never "known to
 * be absent" — the distinction data-model.md's "when applicable" already
 * anticipates.
 */
export interface AuditRequestContextSnapshot {
  readonly actorUserId?: string | undefined;
  readonly ipAddress?: string | undefined;
  readonly userAgent?: string | undefined;
  readonly sessionId?: string | undefined;
  readonly correlationId?: string | undefined;
}

/**
 * The fully-populated row `AuditEventWriterPort` persists. Never
 * constructed by a caller directly — `AuditRecorder` is the only producer
 * — which is what makes it safe for every field the database requires
 * `NOT NULL` (`id`, `occurredAt`, `actorLabel`, `action`, `entityType`,
 * `correlationId`, `outcome`) to be required here too.
 */
export interface AuditEventRecord {
  readonly id: string;
  readonly occurredAt: Date;
  readonly actorUserId?: string | undefined;
  readonly actorLabel: string;
  readonly action: string;
  readonly entityType: AuditEntityType;
  readonly entityId?: string | undefined;
  readonly previousValues?: Record<string, unknown> | undefined;
  readonly newValues?: Record<string, unknown> | undefined;
  readonly organizationalUnitId?: string | undefined;
  readonly ipAddress?: string | undefined;
  readonly userAgent?: string | undefined;
  readonly sessionId?: string | undefined;
  readonly correlationId: string;
  readonly outcome: AuditOutcome;
}

/**
 * The input `AuditRecorder.record(...)` accepts (T029). Deliberately
 * narrower than `AuditEventRecord`: everything `AuditRecorder` can derive
 * itself from `RequestContext` (actor id, IP, user agent, session id,
 * correlation id) or generate (`id`, `occurredAt`) is NOT accepted here —
 * a caller cannot supply it even by accident, let alone omit it. What
 * remains — `action`, `entityType`, `actorLabel` — has no optional
 * variant and no default, so TypeScript itself rejects a call site that
 * forgets one; there is no way to "forget" `actorLabel` and get a
 * `null`/empty value written silently instead.
 *
 * `outcome` defaults to `SUCCESS` when omitted (the overwhelmingly common
 * case per FR-032); `FAILURE`/`DENIED` are recorded by passing it
 * explicitly (FR-037 — the interceptor that does this automatically for
 * denied authorization is a later task, T040a).
 */
export interface RecordAuditEventInput {
  /** Business action name, e.g. `risk.accepted` — never a table name. */
  readonly action: string;
  readonly entityType: AuditEntityType;
  /**
   * Denormalized actor display name (data-model.md §5): captured at the
   * moment of the action so history reads correctly even after the actor
   * is later renamed or deactivated. The caller already has the acting
   * user loaded (it is the one performing the operation), so this is
   * cheap to supply and is required rather than looked up here — looking
   * it up would need a repository dependency this application-layer
   * service must not have (ADR-011: application depends on domain only).
   */
  readonly actorLabel: string;
  readonly entityId?: string | undefined;
  /** Raw candidate values — filtered through the entity type's field
   * allow-list (T030) before ever reaching the database. Passing a field
   * here that is not allow-listed does not audit-leak it; it is dropped. */
  readonly previousValues?: Readonly<Record<string, unknown>> | undefined;
  readonly newValues?: Readonly<Record<string, unknown>> | undefined;
  readonly organizationalUnitId?: string | undefined;
  readonly outcome?: AuditOutcome | undefined;
}
